                .arg(Arg::new("site-path").short('s').long("site-path").value_name("SITE_PATH").help("Path to your oranda site"))
                .subcommand_required(true)
                .arg_required_else_help(true)
                .subcommand(
                    Command::new("ci").about("Generates a CI file that can be used to deploy your site")
                        .arg(Arg::new("ci").long("ci").value_name("CI").default_value("github").value_parser(["github"]).help("What CI to generate a file for"))
                        .arg(Arg::new("output-path").short('o').long("output-path").value_name("OUTPUT_PATH").help("Path to the output file"))
                        .arg(Arg::new("site-path").short('s').long("site-path").value_name("SITE_PATH").help("Path to your oranda site"))
                )
        )
        .subcommand(Command::new("config-schema").hide(true).arg(Arg::new("output").long("output").value_name("OUTPUT").help("Write the config schema to the named file instead of stdout")))
        .subcommand(Command::new("generate-css").hide(true).arg(Arg::new("out-dir").long("out-dir").value_name("OUT_DIR")))
}
fn main() {
    let mut cmd = build_cli();
    // try to get help for --help and -h
    let args_list = vec![
        vec!["executable","--help"],
        vec!["executable","-h"],
        vec!["executable","build","--help"],
        vec!["executable","build","-h"],
        vec!["executable","dev","--help"],
        vec!["executable","dev","-h"],
        vec!["executable","serve","--help"],
        vec!["executable","serve","-h"],
        vec!["executable","generate","--help"],
        vec!["executable","generate","-h"],
        vec!["executable","generate","ci","--help"],
        vec!["executable","generate","ci","-h"],
        vec!["executable","config-schema","--help"],
        vec!["executable","config-schema","-h"],
        vec!["executable","generate-css","--help"],
        vec!["executable","generate-css","-h"],
