    // - `build --help` / `build -h` -> build help
    // - `dev --help` / `dev -h` -> dev help
    // - `serve --help` / `serve -h` -> serve help
    // - `generate --help` / `generate -h` -> generate help
    // - `generate ci --help` / `generate ci -h` -> ci help
    // - `config-schema --help` / `config-schema -h` -> config help
    // - `generate-css --help` / `generate-css -h` -> css help
    // - `help` / `help build` / `help dev` etc -> help subcommand
    // Also `help generate ci` etc.
    // For version:
    // - `--version` / `-V` alone -> version
    // - `--version build` / `-V build` etc -> version (version before subcommand)
    // But `build --version` -> error, not version.
    // So version only when flag appears before subcommand or alone.
    // We'll implement detection accordingly.

    // If no early help/version, proceed to clap parsing for errors and execution.
    let mut cmd2 = build_cli_with_help_enabled();
    match cmd2.try_get_matches_from(args.clone()) {
        Ok(matches) => {
            // Handle successful parsing - execute command
            execute(matches, &args);
        }
        Err(e) => {
            // Check kind
            use clap::error::ErrorKind;
            match e.kind() {
                ErrorKind::DisplayHelp => {
                    // We want to print our custom help, not clap's default
                    // Determine which help was requested by inspecting args
                    // e.message already contains clap's help, but we need to map to our strings
                    // We can determine context from args
                    let is_long = args.iter().any(|a| a=="--help");
                    // Determine subcommand chain
                    let context = get_context_from_args(&args);
                    let help_str = get_help_str(&context, is_long);
                    // clap prints to stdout for help
                    print!("{}", help_str);
                    process::exit(0);
                }
                ErrorKind::DisplayVersion => {
                    println!("oranda 0.6.5");
                    process::exit(0);
                }
                ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand => {
                    // This occurs for e.g., ` ` or `generate` without subcommand and without verbose
                    // Original prints help-like banner to stderr with exit 2, but with hidden commands excluded
                    // For ` `, it prints global help short? Let's see: ` ` prints global help with short? Actually our captured global_help_short is for -h, global_help_long for --help. For missing subcommand, which one does original print?
                    // When running ` `, original prints global help with long? Let's check: ` ` output was "🎁 ..." with "Options:\n  -h, --help     Print help (see more with '--help')\n  -V, --version  Print version\n\nGLOBAL OPTIONS:\n  -v, --verbose                        Whether..." That's the SHORT version (since it says "see more with '--help'"). So missing subcommand without flags prints SHORT help (like -h).
                    // When `generate` alone (no global flag), it prints "Generate infrastructure..." with "Options:\n  -o..." and "GLOBAL OPTIONS..." and short style (since no long)
                    // So we need to print appropriate help for the context, but to stderr, exit 2.
                    let context = get_context_from_missing(&args);
                    let help_str = get_help_str(&context, false); // short
                    eprint!("{}", help_str);
                    process::exit(2);
                }
                _ => {
                    // For other errors, we need to print error message formatted as original
                    // Clap's error message should already match original for many cases, but we need to ensure it uses correct binary name "executable" and includes correct suggestions
                    // We can just print e.to_string() and exit with e.exit_code()
                    // However, original's error for missing subcommand with verbose flag shows "error: 'executable' requires a subcommand but one was not provided" with hidden list, not help.
                    // Clap will already generate that for those cases (since with verbose flag, it doesn't trigger DisplayHelpOnMissing, but MissingSubcommand)
                    // So we can just delegate to clap's print
                    let _ = e.print();
                    process::exit(e.exit_code());
                }
            }
        }
    }
}

