        // Let's check another: `{"a": "b" "c": "d"}` with first key a offset 3, content `{"a": "b" "c": "d"}` -> positions: 0:{,1:",2:a,3:",4::,5: ,6:",7:b,8:",... So offset 3 is closing quote again. So pattern holds: offset points to closing quote.
        // For `{"build":{"path":"public"}}` with unknown field path at top? Actually build's path is inside build object. The offset for path was 15? Let's see content `{"build":{"path":"public"}}` -> indexes: 0:{,1:",2:b,3:u,4:i,5:l,6:d,7:",8::,9:{,10:",11:p,12:a,13:t,14:h,15:",16::,17:",18:p,... So offset 15 is closing quote for "path". So again closing quote.
        // So offset is position of closing quote of the key.
        pos + pattern.len() -1
    } else {
        0
    }
}

fn extract_offset(e: &serde_json::Error, content: &str) -> (usize, usize) {
