fn handle_verbose_and_format(args: &[String]) -> (bool, OutputFormat, Vec<String>) {
    let mut verbose = false;
    let mut format = OutputFormat::Human;
    let mut remaining = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg=="-v" || arg=="--verbose" {
            verbose = true;
            i+=1;
        } else if arg=="--output-format" {
            if i+1 < args.len() {
                if let Some(f) = OutputFormat::from_str(&args[i+1]) {
                    format = f;
                } else {
                    // will be handled by clap error later
                    remaining.push(arg.clone());
                    remaining.push(args[i+1].clone());
                }
                i+=2;
            } else {
                remaining.push(arg.clone());
                i+=1;
            }
        } else if arg.starts_with("--output-format=") {
            let val = arg.splitn(2,'=').nth(1).unwrap();
            if let Some(f) = OutputFormat::from_str(val) {
                format = f;
            } else {
                remaining.push(arg.clone());
            }
            i+=1;
        } else {
            remaining.push(arg.clone());
            i+=1;
        }
    }
    (verbose, format, remaining)
}

