fn get_context_from_args(args: &[String]) -> Vec<String> {
    // Determine subcommand chain for help
    // Find help flag position
    let mut help_pos = None;
    let mut help_long = false;
    for (i, a) in args.iter().enumerate() {
        if a=="--help" { help_pos = Some(i); help_long = true; break; }
        if a=="-h" { help_pos = Some(i); help_long = false; break; }
    }
    if let Some(pos) = help_pos {
        // Collect subcommands before help flag
        let mut ctx = Vec::new();
        for j in 1..pos {
            let arg = &args[j];
            if arg.starts_with("-") { continue; }
            // If arg is known subcommand, add
            if ["build","dev","serve","generate","config-schema","generate-css","ci","help"].contains(&arg.as_str()) {
                ctx.push(arg.clone());
                if arg=="generate" && j+1<pos && args[j+1]=="ci" { ctx.push("ci".to_string()); break; }
            }
        }
        return ctx;
    }
    // For missing subcommand case, determine context based on args without help
    let mut ctx = Vec::new();
    for j in 1..args.len() {
        let arg = &args[j];
        if arg.starts_with("-") { continue; }
        if arg=="--output-format" { continue; }
        // skip value for output-format
        // This is complex; for missing case, we can just look for generate
        if arg=="generate" { ctx.push("generate".to_string()); break; }
    }
    ctx
}
fn get_context_from_missing(args: &[String]) -> Vec<String> {
    // Determine context for missing subcommand help
    // Look for generate before missing
    for a in args.iter() {
        if a=="generate" { return vec!["generate".to_string()]; }
    }
    vec![]
}
fn get_help_str(context: &[String], is_long: bool) -> String {
    if context.is_empty() {
        if is_long { GLOBAL_HELP_LONG.to_string() } else { GLOBAL_HELP_SHORT.to_string() }
    } else if context==["build"] {
        if is_long { BUILD_HELP_LONG.to_string() } else { BUILD_HELP_SHORT.to_string() }
    } else if context==["dev"] {
        if is_long { DEV_HELP_LONG.to_string() } else { DEV_HELP_SHORT.to_string() }
    } else if context==["serve"] {
        if is_long { SERVE_HELP_LONG.to_string() } else { SERVE_HELP_SHORT.to_string() }
    } else if context==["generate"] {
        if is_long { GENERATE_HELP_LONG.to_string() } else { GENERATE_HELP_SHORT.to_string() }
    } else if context==["generate","ci"] || context==["ci"] {
        if is_long { GENERATE_CI_HELP_LONG.to_string() } else { GENERATE_CI_HELP_SHORT.to_string() }
    } else if context==["config-schema"] {
        if is_long { CONFIG_SCHEMA_HELP_LONG.to_string() } else { CONFIG_SCHEMA_HELP_SHORT.to_string() }
    } else if context==["generate-css"] {
        if is_long { GENERATE_CSS_HELP_LONG.to_string() } else { GENERATE_CSS_HELP_SHORT.to_string() }
    } else {
        // fallback to global
        if is_long { GLOBAL_HELP_LONG.to_string() } else { GLOBAL_HELP_SHORT.to_string() }
    }
}

