fn parse_config(content: &str, filename: &str) -> Result<(), ParseError> {
    // Use serde_json to parse, and map errors to our diagnostic
    let v: Result<serde_json::Value, _> = serde_json::from_str(content);
    match v {
        Ok(val) => {
            // Need to validate against schema: unknown fields, type errors
            // We'll try to deserialize into our config struct
            #[derive(Deserialize, Debug)]
            struct OrandaLayer {
                #[serde(rename = "$schema")]
                schema: Option<String>,
